        start_idx = None
        for i in range(idx, -1, -1):
            line_i = lines[i]
            if line_i.strip() == '{':  # standalone {
                start_idx = i
                break
            elif line_i.startswith('    ') and '{' in line_i and '}' not in line_i:
                # This is the start of an object like "    {"
                start_idx = i
                break
        if start_idx is None:
